-- Dynamic items + Greater Rifts: base rows (run 1st, after world has created the dynamic item tables).
-- Every id here is unused in stock PEQ (database 9328). Run 00_check_ids.sql first on a customized database.
-- Safe to run again (REPLACE / NOT EXISTS).

START TRANSACTION;

-- Stat-less shell the class set, jewelry and augment items are copied from (No Trade, aug slots)
UPDATE items SET Name = 'Dynamic Item Shell', lore = 'Dynamic Item Shell' WHERE id = 900101;

-- Chronal Shard: the rift reward currency (alternate currency 2)

-- Rift NPC types: controller (invisible), Guardian, pylon, return portal, Chronal Quartermaster (tier 1 armor
-- vendor), and the four Anachronism archetypes (Vanguard, Evoker, Dominator, Executioner)

-- Spawngroups the rift zone setup places (archetypes at every spawn point, the controller at the entry)

-- The Void (thevoida) is the rift hub. Stock PEQ makes it GM-only (min_status 255): open it
UPDATE zone SET min_status = 0 WHERE short_name = 'thevoida' AND version = 0;

-- Zebuxoruk (stock NPC 459000 in The Void) opens the rifts: plain class so a right-click doesn't open a shop window
UPDATE npc_types SET class = 1, lastname = 'Chronal Fabric' WHERE id = 459000;
UPDATE spawn2 SET x = 84.71, y = -48.74, z = 4.15, heading = 437.75 WHERE id = 130090 AND zone = 'thevoida';

-- Chronal Quartermaster in The Void (03_tier_gear.sql moves it into the vendor line)
SELECT 5003837, 'thevoida', 0, 80.52, 50.86, 4.33, 358.25, 60, 0 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM spawn2 WHERE spawngroupID = 5003837);

COMMIT;
